text:
{{
  (() => {
    // 1. Récupération du total TTC de l'intervention
    const totalTTC = Get_Detail_Intervention.data[0]?.TOTAL_TTC || 0;
    const texteTotal = "TOTAL TTC : " + totalTTC + " €";

    // 2. Recherche de lignes avec une prise en charge spécifique
    const lignes = Table_Lignes_Intervention.tableData || [];

    // On isole les prises en charge différentes de "Client"
    const autresPrisesEnCharge = lignes
      .map(row => row.Prise_En_Charge)
      .filter(charge => charge && charge.toUpperCase() !== 'CLIENT');

    // 3. Si tout est payé par le client, on affiche juste le total
    if (autresPrisesEnCharge.length === 0) {
      return texteTotal;
    }

    // 4. S'il y a des prises en charge différentes, on crée l'alerte rouge
    // new Set() supprime les doublons (ex: s'il y a 3 pièces en garantie, on l'écrit 1 fois)
    const uniques = [...new Set(autresPrisesEnCharge)];

    // On ajoute un saut de ligne et l'alerte après le total
    return texteTotal + "\n⚠️ Prise en charge : " + uniques.join(", ");
  })()
}}

textColor:
{{
  (Table_Lignes_Intervention.tableData && Table_Lignes_Intervention.tableData.some(row => row.Prise_En_Charge && row.Prise_En_Charge.toUpperCase() !== 'CLIENT'))
    ? "#dc2626"  // Rouge si prise en charge autre
    : "#000000"  // Noir (ou ta couleur par défaut) si tout est normal
}}
